{
  "status": "SUPPORTED",
  "task_summary": "Identify components, fasten, and place tool.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "fastener_component",
        "entity_kind": "OBJECT",
        "function": "Provides the material connection between parts.",
        "required_count": 1,
        "binding_policy": "DISTINCT"
      ,
      "candidate_categories": [
        "screw",
        "bolt",
        "nut",
        "pin"
      ],
      "required_properties": [
        "compatible_with_workpiece",
        "drivable_by_tool"
      ]
    },
    {
      "id": "fastening_tool",
      "entity_kind": "OBJECT",
      "function": "Implements the mechanical force to apply the fastener.",
      "required_count": 1,
      "binding_policy": "REUSABLE"
    ,
      "candidate_categories": [
        "screwdriver",
        "wrench",
        "spanner"
      ],
      "required_properties": [
        "can_drive_fastener"
      ]
    },
    {
      "id": "workpiece",
      "entity_kind": "FIXED_TARGET",
      "function": "The object or structure receiving the fastener.",
      "required_count": 1,
      "binding_policy": "SHARED"
    ,
      "candidate_categories": [
        "part",
        "assembly",
        "panel"
      ],
      "required_properties": [
        "has_fastening_point"
      ]
    },
    {
      "id": "workbench",
      "entity_kind": "REGION",
      "function": "The stable surface where the tool is returned.",
      "required_count": 1,
      "binding_policy": "SHARED"
    ,
      "candidate_categories": [
        "table",
        "desk",
        "bench"
      ],
      "required_properties": [
        "stable",
        "flat"
      ]
    }
  ],
  "functional_relations": [
    {
      "id": "fits_into",
      "relation": "The fastener_component is designed to fit into or onto the workpiece.",
      "participant_roles": [
        "fastener_component",
        "workpiece"
      ]
    ,
      "required": true
    },
    {
      "id": "operates_on",
      "relation": "The fastening_tool is used to drive or tighten the fastener_component.",
      "participant_roles": [
        "fastening_tool",
        "fastener_component"
      ]
    ,
      "required": true
    }
  ],
  "operation_pairings": [
    {
      "id": "identify_components",
      "operation": "Locate and verify the presence of compatible fastener and tool.",
      "participant_roles": [
        "fastener_component",
        "fastening_tool"
      ]
    ,
      "operation_count": 1
    },
    {
      "id": "perform_fastening",
      "operation": "Apply the fastener_component to the workpiece using the fastening_tool.",
      "participant_roles": [
        "fastening_tool",
        "fastener_component",
        "workpiece"
      ]
    ,
      "operation_count": 1
    },
    {
      "id": "place_equipment",
      "operation": "Deposit the fastening_tool on the workbench.",
      "participant_roles": [
        "fastening_tool",
        "workbench"
      ]
    ,
      "operation_count": 1
    }
  ]
},
"observation_guidance": {
  "visible_candidates_per_role": {
    "fastener_component": [],
    "fastening_tool": [
      {
        "label": "yellow_handle_object",
        "visual_description": "Yellow object resembling a screwdriver handle located on the table surface."
      }
    ],
    "workpiece": [],
    "workbench": [
      {
        "label": "wooden_table",
        "visual_description": "Wooden table surface with drawers underneath."
      }
    ]
  },
  "inspectable_regions": [
    {
      "id": "left_drawer",
      "label": "Left Drawer",
      "visual_description": "Closed blue drawer under the left side of the table.",
      "reason": "Closed storage structure likely containing small parts or tools."
    },
    {
      "id": "right_drawer",
      "label": "Right Drawer",
      "visual_description": "Closed blue drawer under the right side of the table.",
      "reason": "Closed storage structure likely containing small parts or tools."
    },
    {
      "id": "cabinet",
      "label": "Cabinet",
      "visual_description": "Tall blue cabinet against the back wall.",
      "reason": "Closed storage structure likely containing larger tools or components."
    }
  ],
  "inspection_order": [
    "left_drawer",
    "right_drawer",
    "cabinet"
  ]
}
,
